#!/usr/bin/env node
// Generates isolated-agent wrappers from team personas that declare `subagent: true`.
// The persona Markdown under .pipes/team/ stays canonical; each generated file is a thin,
// read-only pointer to it. Only targets with an isolated-agent format receive files:
// Claude Code reads .claude/agents/. Other targets fall back to the persona file itself.
const fs = require('node:fs');
const path = require('node:path');

const PIPE_ROOT = path.resolve(__dirname, '..', '..');
const WORKSPACE_ROOT = path.dirname(PIPE_ROOT);
const BT = String.fromCharCode(96);
const MARKER = '<!-- pipes-agent:generated -->';
const TARGETS = { claude: { id: 'claude', root: '.claude/agents' } };
const WRITE_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit']);

function parseArgs(argv) {
  const options = { check: false, root: WORKSPACE_ROOT, pipeRoot: PIPE_ROOT };
  for (let index = 2; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--check') options.check = true;
    else if (arg === '--root') { options.root = path.resolve(argv[index + 1] || ''); index += 1; }
    else throw new Error('Unknown argument: ' + arg);
  }
  return options;
}

function frontmatter(content) {
  const block = String(content).match(/^---\r?\n([\s\S]*?)\r?\n---/)?.[1] || '';
  const meta = {};
  for (const line of block.split(/\r?\n/)) {
    const item = line.match(/^([a-z][a-z0-9_]*):\s*(.*)$/i);
    if (item) meta[item[1]] = item[2].trim().replace(/^["']|["']$/g, '');
  }
  return meta;
}

function discoverAgents(pipeRoot = PIPE_ROOT) {
  const dir = path.join(pipeRoot, 'team');
  return fs.readdirSync(dir)
    .filter((name) => /^[a-z][a-z0-9-]*\.md$/.test(name))
    .sort()
    .map((name) => ({ name, meta: frontmatter(fs.readFileSync(path.join(dir, name), 'utf8')) }))
    .filter(({ meta }) => meta.subagent === 'true')
    .map(({ name, meta }) => {
      const id = name.slice(0, -3);
      const tools = String(meta.subagent_tools || '').split(',').map((tool) => tool.trim()).filter(Boolean);
      if (!meta.subagent_description) throw new Error(name + ' declares subagent: true without subagent_description.');
      if (!tools.length) throw new Error(name + ' declares subagent: true without subagent_tools.');
      const writable = tools.filter((tool) => WRITE_TOOLS.has(tool));
      if (writable.length) throw new Error(name + ' isolated agents are read-only; remove ' + writable.join(', ') + ' from subagent_tools.');
      return { id, title: meta.title || id, description: meta.subagent_description, tools, canonicalPath: '.pipes/team/' + name };
    });
}

function renderAgent(agent) {
  return [
    '---',
    'name: ' + agent.id,
    'description: ' + JSON.stringify(agent.description),
    'tools: ' + agent.tools.join(', '),
    '---',
    MARKER,
    '',
    'Generated by Pipes from ' + BT + agent.canonicalPath + BT + '. Do not edit; change the persona and regenerate.',
    '',
    'You are the Pipes ' + BT + agent.id + BT + ' role running as an isolated agent.',
    '',
    '1. Read ' + BT + agent.canonicalPath + BT + ' first. Its `## Isolated Agent Mode` section is your contract.',
    '2. Read ' + BT + '.pipes/ai-instructions/core-workflows.md' + BT + ' and only the rules, records, and files the task needs.',
    '3. You are read-only. Use shell commands only to inspect, build, or test. Never edit files, stage, commit, push, or approve anything.',
    '4. Return the report your persona defines, with evidence paths, and stop.',
    '',
  ].join('\n');
}

function generate(options = {}) {
  const root = options.root || WORKSPACE_ROOT;
  const agents = discoverAgents(options.pipeRoot || PIPE_ROOT);
  const results = [];
  for (const target of Object.values(TARGETS)) {
    const dir = path.join(root, target.root);
    const wanted = new Set();
    for (const agent of agents) {
      const file = path.join(dir, agent.id + '.md');
      wanted.add(file);
      const next = renderAgent(agent);
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
      if (current !== null && !current.includes(MARKER)) throw new Error('Refusing to overwrite unmanaged agent ' + path.relative(root, file));
      const action = current === next ? 'unchanged' : current === null ? 'created' : 'updated';
      if (action !== 'unchanged' && !options.check) {
        fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(file, next, 'utf8');
      }
      results.push({ target: target.id, file: path.relative(root, file), action });
    }
    if (fs.existsSync(dir)) {
      for (const name of fs.readdirSync(dir).filter((file) => file.endsWith('.md'))) {
        const file = path.join(dir, name);
        if (wanted.has(file) || !fs.readFileSync(file, 'utf8').includes(MARKER)) continue;
        if (!options.check) fs.rmSync(file);
        results.push({ target: target.id, file: path.relative(root, file), action: 'removed' });
      }
    }
  }
  return { results, stale: results.some((item) => item.action !== 'unchanged') };
}

function main() {
  const options = parseArgs(process.argv);
  const { results, stale } = generate(options);
  for (const item of results) console.log((options.check ? '? ' : '✓ ') + item.target + ' ' + item.file + ' ' + item.action);
  if (options.check && stale) {
    process.stderr.write('Generated agents are stale; run assemble-agents.cjs.\n');
    process.exitCode = 1;
  }
}

if (require.main === module) {
  try { main(); }
  catch (error) { process.stderr.write(error.message + '\n'); process.exitCode = 1; }
}

module.exports = { discoverAgents, generate, parseArgs, renderAgent, MARKER };
